import{_ as o,o as t,c as a,ai as i}from"./chunks/framework.C33Uq6m-.js";const u=JSON.parse('{"title":"Tool Workshop","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/tool-workshop.md","filePath":"en/guide/tool-workshop.md"}'),n={name:"en/guide/tool-workshop.md"};function r(l,e,s,h,c,d){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="tool-workshop" tabindex="-1">Tool Workshop <a class="header-anchor" href="#tool-workshop" aria-label="Permalink to &quot;Tool Workshop&quot;">​</a></h1><p>The Tool Workshop is a visual canvas for building, editing, and testing tool definitions that models can call during chat.</p><p><strong>Sidebar item:</strong> Tool Workshop <strong>Route:</strong> <code>/tools</code></p><h2 id="interface-overview" tabindex="-1">Interface Overview <a class="header-anchor" href="#interface-overview" aria-label="Permalink to &quot;Interface Overview&quot;">​</a></h2><p>The page features a <strong>node-based canvas</strong> powered by Vue Flow. Each tool is represented as a visual node showing its name, description, parameters, and implementation body.</p><h2 id="creating-tools" tabindex="-1">Creating Tools <a class="header-anchor" href="#creating-tools" aria-label="Permalink to &quot;Creating Tools&quot;">​</a></h2><h3 id="from-templates" tabindex="-1">From Templates <a class="header-anchor" href="#from-templates" aria-label="Permalink to &quot;From Templates&quot;">​</a></h3><p>Click <strong>Templates</strong> to browse 15+ built-in templates including:</p><ul><li>Web fetch (HTTP requests)</li><li>Calculator</li><li>Google Calendar / Gmail integration</li><li>Regex tester</li><li>Date/time utilities</li><li>And more</li></ul><h3 id="from-scratch" tabindex="-1">From Scratch <a class="header-anchor" href="#from-scratch" aria-label="Permalink to &quot;From Scratch&quot;">​</a></h3><p>Click <strong>Add Tool</strong> to create a blank tool node. Fill in:</p><ul><li><strong>Name</strong> — The function name (used by the model)</li><li><strong>Description</strong> — What the tool does (helps the model decide when to use it)</li><li><strong>Parameters</strong> — JSON Schema-defined inputs</li><li><strong>Implementation</strong> — TypeScript function body</li></ul><h2 id="editing-tools" tabindex="-1">Editing Tools <a class="header-anchor" href="#editing-tools" aria-label="Permalink to &quot;Editing Tools&quot;">​</a></h2><h3 id="inline-code-editing" tabindex="-1">Inline Code Editing <a class="header-anchor" href="#inline-code-editing" aria-label="Permalink to &quot;Inline Code Editing&quot;">​</a></h3><p>Each tool node has a full <strong>CodeMirror 6</strong> editor with TypeScript syntax highlighting. Edit the implementation directly on the canvas.</p><h3 id="code-panel-bidirectional-sync" tabindex="-1">Code Panel (Bidirectional Sync) <a class="header-anchor" href="#code-panel-bidirectional-sync" aria-label="Permalink to &quot;Code Panel (Bidirectional Sync)&quot;">​</a></h3><p>Open the <strong>Code Panel</strong> to see all tools as combined TypeScript source code. This uses a <strong>Recast AST parser</strong> for bidirectional synchronization:</p><ul><li>Edit code in the panel → nodes update on the canvas</li><li>Edit nodes on the canvas → code updates in the panel</li></ul><h3 id="schema-viewer" tabindex="-1">Schema Viewer <a class="header-anchor" href="#schema-viewer" aria-label="Permalink to &quot;Schema Viewer&quot;">​</a></h3><p>Click the schema icon on any tool to see its auto-generated <strong>OpenAI-compatible JSON schema</strong>. One-click copy for use in other systems.</p><h2 id="probe-pick" tabindex="-1">Probe &amp; Pick <a class="header-anchor" href="#probe-pick" aria-label="Permalink to &quot;Probe &amp; Pick&quot;">​</a></h2><p>Point at any API URL to:</p><ol><li><strong>Probe</strong> the endpoint — send a request and inspect the response</li><li><strong>Browse the JSON tree</strong> — expand/collapse the response structure</li><li><strong>Pick fields</strong> — select the data you need</li><li><strong>Auto-generate</strong> fetch code and parameter mappings</li></ol><h2 id="openapi-discovery" tabindex="-1">OpenAPI Discovery <a class="header-anchor" href="#openapi-discovery" aria-label="Permalink to &quot;OpenAPI Discovery&quot;">​</a></h2><p>If an API has an OpenAPI/Swagger specification:</p><ol><li>Enter the spec URL</li><li>LLMxRay parses the spec automatically</li><li>Browse available endpoints</li><li>Pick an endpoint to auto-generate a tool definition</li></ol><h2 id="live-execution" tabindex="-1">Live Execution <a class="header-anchor" href="#live-execution" aria-label="Permalink to &quot;Live Execution&quot;">​</a></h2><p>During chat, when the model calls a tool:</p><ul><li>The corresponding node <strong>pulses</strong> on the canvas</li><li>Execution results appear as an <strong>overlay</strong> on the node</li><li>The tool call timeline (in Chat Diagnostics) links back to the canvas</li></ul><h2 id="tool-call-optimizer" tabindex="-1">Tool Call Optimizer <a class="header-anchor" href="#tool-call-optimizer" aria-label="Permalink to &quot;Tool Call Optimizer&quot;">​</a></h2><p>When a model calls a tool during chat, an <strong>&quot;Optimize this Tool&quot;</strong> button appears on the result. Click it to open the Response Optimizer Drawer:</p><ol><li><strong>Visualize</strong> the API response as an interactive JSON tree</li><li><strong>Select</strong> only the fields the model actually needs</li><li><strong>Auto-generate</strong> optimized fetch code with field extraction</li><li><strong>Create</strong> a new optimized tool in the Workshop with one click</li></ol><h2 id="persistence" tabindex="-1">Persistence <a class="header-anchor" href="#persistence" aria-label="Permalink to &quot;Persistence&quot;">​</a></h2><p>Tool definitions, node positions, mappings, and probe configurations are all persisted and survive browser refreshes.</p><h2 id="exporting-tools" tabindex="-1">Exporting Tools <a class="header-anchor" href="#exporting-tools" aria-label="Permalink to &quot;Exporting Tools&quot;">​</a></h2><p>Click the <strong>Export</strong> button to download your tool definitions as <strong>JSON</strong>. The export includes tool names, descriptions, parameter schemas, and implementation bodies — everything needed to reimport or share your tools. See the <a href="./export.html">Export guide</a> for details on all export options.</p><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li>Start with a template and customize it — faster than building from scratch.</li><li>Use the <strong>Schema Viewer</strong> to verify your tool definition matches what models expect.</li><li>The <strong>Probe &amp; Pick</strong> workflow is the fastest way to wrap a REST API as a tool.</li><li>Tools are automatically available in chat when enabled.</li></ul>',38)])])}const g=o(n,[["render",r]]);export{u as __pageData,g as default};
